SELECT DISTINCT ?name_gene_tad
WHERE {
GRAPH <http://rdf.biogateway.eu/graph/gene> {
    ?uri_gen rdfs:subClassOf <http://semanticscience.org/resource/SIO_010035>;
             skos:prefLabel "GATA3";
             obo:BFO_0000050 ?chromosome;
             obo:GENO_0000894 ?start_position_gene;
             obo:GENO_0000895 ?end_position_gene;
             obo:RO_0002162 ?taxon.
  }
GRAPH <http://rdf.biogateway.eu/graph/taxon> {
    ?taxon rdfs:label "Homo sapiens".
  }
GRAPH <http://rdf.biogateway.eu/graph/tad> {
	?uri_tad rdfs:subClassOf <http://purl.obolibrary.org/obo/SO_0002304> ;
		obo:BFO_0000050 ?chromosome ;
		obo:GENO_0000894 ?start_position_tad;
        obo:GENO_0000895 ?end_position_tad .
}
GRAPH <http://rdf.biogateway.eu/graph/gene> {
    ?uri_gen_tad rdfs:subClassOf <http://semanticscience.org/resource/SIO_010035>;
                 obo:BFO_0000050 ?chromosome;
                 obo:GENO_0000894 ?start_position_gene_tad;
                 obo:GENO_0000895 ?end_position_gene_tad;
                 skos:prefLabel ?name_gene_tad.

}
FILTER(?start_position_gene_tad >= ?start_position_tad && ?end_position_gene_tad <= ?end_position_tad)
FILTER(?start_position_tad <= ?start_position_gene && ?end_position_tad >= ?end_position_gene)
}

