SELECT DISTINCT ?protein_name 
WHERE {
GRAPH <http://rdf.biogateway.eu/graph/gene> {
?gene rdfs:subClassOf <http://semanticscience.org/resource/SIO_010035>;
          sio:SIO_010078 ?protein;
          obo:RO_0002162 ?taxon.
}
  GRAPH <http://rdf.biogateway.eu/graph/prot2bp> {
    ?protein obo:RO_0002331 ?biological_process.
  }
  GRAPH <http://rdf.biogateway.eu/graph/prot> {
    ?protein rdfs:subClassOf <http://semanticscience.org/resource/SIO_010043>;
    skos:prefLabel ?protein_name;
    obo:RO_0002162 ?taxon.
  }
  GRAPH <http://rdf.biogateway.eu/graph/go> {
    ?biological_process rdfs:label ?biological_process_name;
	owl:hasExactSynonym ?synonym_name_biological_process.
    FILTER(REGEX(?biological_process_name, "cytokine-mediated signaling pathway", "i") || REGEX(?synonym_name_biological_process, "cytokine-mediated signaling pathway", "i"))
  }
  GRAPH <http://rdf.biogateway.eu/graph/gene2phen> {
    ?gene obo:RO_0002331 ?disease.
  }
  GRAPH <http://rdf.biogateway.eu/graph/omim> {
    ?disease skos:prefLabel ?disease_name;
    skos:altLabel ?alternative_disease_name.
    FILTER(REGEX(?disease_name, "autoimmune", "i") || REGEX(?alternative_disease_name,"autoimmune","i"))
  }
  GRAPH <http://rdf.biogateway.eu/graph/taxon> {
    ?taxon rdfs:label "Homo sapiens".
  }
}

